insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5239,"materia":"enf","nivel":0,"enunciado":"Em adulto, a frequência cardíaca abaixo de 60 batimentos por minuto é chamada de:","opcoes":["Bradicardia","Taquicardia","Arritmia sinusal respiratória","Taquipneia"],"explicacao":"Acima de 100 bpm em repouso: taquicardia."},{"id":5240,"materia":"enf","nivel":0,"enunciado":"A coloração azulada da pele e das mucosas, por falta de oxigenação, é chamada de:","opcoes":["Cianose","Icterícia","Palidez","Eritema"],"explicacao":"Costuma aparecer primeiro nos lábios e nas extremidades."},{"id":5241,"materia":"enf","nivel":0,"enunciado":"Vômito com sangue é chamado de:","opcoes":["Hematêmese","Hemoptise, quando o sangue vem do estômago","Hematúria","Epistaxe"],"explicacao":"Hemoptise é a eliminação de sangue pela tosse, vindo das vias respiratórias."},{"id":5242,"materia":"enf","nivel":0,"enunciado":"Fezes escuras, pastosas e com cheiro forte, por sangue digerido, são chamadas de:","opcoes":["Melena","Esteatorreia","Enterorragia","Constipação"],"explicacao":"Indicam, em geral, sangramento na parte alta do tubo digestivo."},{"id":5243,"materia":"enf","nivel":0,"enunciado":"Diante de sangramento pelo nariz (epistaxe), a orientação inicial é:","opcoes":["Sentar, inclinar a cabeça para a frente e apertar as asas do nariz","Deitar de costas com a cabeça bem inclinada para trás, olhando para cima","Assoar o nariz com força várias vezes","Colocar algodão com álcool dentro do nariz"],"explicacao":"Inclinar para trás faz o sangue descer para a garganta."},{"id":5244,"materia":"enf","nivel":0,"enunciado":"A dificuldade para engolir é chamada de:","opcoes":["Disfagia","Dispepsia","Disúria","Disfonia"],"explicacao":"É comum depois de AVC e aumenta o risco de broncoaspiração."},{"id":5245,"materia":"enf","nivel":0,"enunciado":"A perda ou dificuldade de linguagem depois de um AVC é chamada de:","opcoes":["Afasia","Ataxia","Apraxia de marcha","Anosmia"],"explicacao":"Pode afetar a fala, a compreensão, a leitura e a escrita."},{"id":5246,"materia":"enf","nivel":0,"enunciado":"O exame de sangue que confirma a gravidez detecta o hormônio:","opcoes":["Beta-hCG","Insulina","TSH","Cortisol"],"explicacao":"Também é usado no teste rápido de urina."},{"id":5247,"materia":"enf","nivel":0,"enunciado":"O primeiro leite produzido após o parto, rico em anticorpos, é o:","opcoes":["Colostro","Leite de transição","Leite maduro","Leite posterior"],"explicacao":"Funciona como a 'primeira vacina' do bebê."},{"id":5248,"materia":"enf","nivel":0,"enunciado":"No aleitamento materno exclusivo, o bebê deve mamar:","opcoes":["Em livre demanda, sempre que quiser","Só de 3 em 3 horas, com horário fixo","Só durante o dia","No máximo 5 vezes por dia"],"explicacao":"Mamar sem horário fixo ajuda a manter a produção de leite."},{"id":5249,"materia":"enf","nivel":0,"enunciado":"Diante de uma queimadura leve, a primeira medida é:","opcoes":["Resfriar com água corrente em temperatura ambiente","Passar pasta de dente sobre a pele","Colocar gelo direto na pele até a dor passar por completo","Estourar as bolhas logo"],"explicacao":"Gelo e produtos caseiros pioram a lesão."},{"id":5250,"materia":"enf","nivel":0,"enunciado":"Diante de alguém que levou choque elétrico e ainda está em contato com a fonte, deve-se primeiro:","opcoes":["Desligar a energia antes de tocar na vítima","Puxar a vítima com as mãos o mais rápido possível, sem esperar","Jogar água sobre a vítima","Fazer respiração boca a boca"],"explicacao":"Tocar na vítima antes de cortar a energia expõe o socorrista ao choque."},{"id":5251,"materia":"enf","nivel":0,"enunciado":"A pessoa com diabetes deve ser orientada a cuidar dos pés:","opcoes":["Examinando-os todo dia e cortando as unhas retas","Andando descalça para fortalecer a pele","Cortando as unhas bem curtas e arredondadas nos cantos, rente à pele","Usando bolsa de água quente para aquecer"],"explicacao":"A perda de sensibilidade faz feridas passarem despercebidas."},{"id":5252,"materia":"enf","nivel":0,"enunciado":"Na dengue, não deve ser usado para febre e dor:","opcoes":["AAS (ácido acetilsalicílico)","Dipirona","Paracetamol","Soro de reidratação oral e líquidos"],"explicacao":"O AAS e os anti-inflamatórios aumentam o risco de sangramento."},{"id":5253,"materia":"enf","nivel":0,"enunciado":"A gastrostomia é:","opcoes":["Uma abertura do estômago na parede do abdome","Uma abertura do intestino grosso na parede do abdome","Uma sonda que passa pelo nariz","Uma abertura na traqueia"],"explicacao":"Permite alimentar a pessoa diretamente pelo estômago."},{"id":5254,"materia":"enf","nivel":0,"enunciado":"O órgão que fiscaliza o exercício da enfermagem no estado é o:","opcoes":["Conselho Regional de Enfermagem (Coren)","Ministério da Educação","Conselho Regional de Medicina","Sindicato dos profissionais de enfermagem do estado"],"explicacao":"O Cofen é o conselho federal."},{"id":5255,"materia":"enf","nivel":0,"enunciado":"Na picada de cobra, deve-se:","opcoes":["Lavar o local e levar a vítima logo ao serviço de saúde","Fazer torniquete bem apertado acima da picada e esperar o efeito passar","Cortar o local e sugar o veneno","Passar álcool, querosene ou outra substância caseira"],"explicacao":"Torniquete e cortes pioram a lesão; o tratamento é o soro."},{"id":5256,"materia":"enf","nivel":1,"enunciado":"Pela Resolução Cofen nº 736/2024, o Processo de Enfermagem tem cinco etapas:","opcoes":["Avaliação, diagnóstico, planejamento, implementação e evolução","Admissão, prescrição, medicação, curativo e alta","Coleta de dados, triagem, consulta, exame físico e encaminhamento","Histórico, escuta, alta, retorno e auditoria"],"explicacao":"Ela substituiu a antiga Resolução Cofen nº 358/2009."},{"id":5257,"materia":"enf","nivel":1,"enunciado":"Dentro da equipe de enfermagem, o diagnóstico de enfermagem é:","opcoes":["Privativo do enfermeiro","Feito pelo técnico de enfermagem","Feito por qualquer membro da equipe","Feito pelo médico"],"explicacao":"Técnicos e auxiliares participam das demais etapas, conforme sua competência."},{"id":5258,"materia":"enf","nivel":1,"enunciado":"Pelo Código de Ética de Enfermagem, é um direito do profissional:","opcoes":["Recusar atividades que não sejam de sua competência técnica e legal","Abandonar o plantão sem aviso","Executar qualquer prescrição recebida por telefone ou mensagem, sem conferir","Divulgar dados do paciente nas redes"],"explicacao":"Também pode recusar atividades que não ofereçam segurança."},{"id":5259,"materia":"enf","nivel":1,"enunciado":"Na precaução por gotículas, além da precaução padrão, o profissional deve usar:","opcoes":["Máscara cirúrgica","Máscara N95/PFF2 em qualquer caso","Apenas luvas","Avental impermeável sempre"],"explicacao":"A N95/PFF2 é para precaução por aerossóis."},{"id":5260,"materia":"enf","nivel":1,"enunciado":"A precaução padrão deve ser usada:","opcoes":["Com todos os pacientes, com ou sem diagnóstico de infecção","Só com pacientes com HIV, hepatite ou outra infecção confirmada","Só no centro cirúrgico","Só quando o paciente tem febre"],"explicacao":"Inclui higiene das mãos e EPI conforme o risco de contato com sangue e secreções."},{"id":5261,"materia":"enf","nivel":1,"enunciado":"Na retirada dos EPIs, geralmente se retira primeiro:","opcoes":["As luvas","A máscara","O gorro","Os óculos"],"explicacao":"As luvas são as mais contaminadas; a máscara sai por último, já fora do quarto."},{"id":5262,"materia":"enf","nivel":1,"enunciado":"Resíduos com sangue, como gazes de curativo (grupo A), devem ir para saco:","opcoes":["Branco leitoso, com o símbolo de infectante","Preto, como o lixo comum","Azul, para reciclagem","Verde, junto com o resíduo orgânico da cozinha do hospital"],"explicacao":"Perfurocortantes (grupo E) vão para caixa rígida própria."},{"id":5263,"materia":"enf","nivel":1,"enunciado":"Quando se aperta a pele edemaciada com o dedo e fica uma depressão, é o sinal de:","opcoes":["Godet (cacifo)","Murphy","Blumberg","Homans"],"explicacao":"Ajuda a graduar o edema, de uma a quatro cruzes."},{"id":5264,"materia":"enf","nivel":1,"enunciado":"Na escala de Glasgow, a pessoa que abre os olhos espontaneamente recebe, na abertura ocular:","opcoes":["4 pontos","1 ponto","3 pontos","6 pontos"],"explicacao":"A abertura ocular vai de 1 a 4 pontos."},{"id":5265,"materia":"enf","nivel":1,"enunciado":"Em adulto inconsciente, para checar se há pulso, usa-se o pulso:","opcoes":["Carotídeo, por no máximo 10 segundos","Radial, contando por 1 minuto inteiro","Pedioso, por 30 segundos","Apical, por 2 minutos"],"explicacao":"Na dúvida, inicia-se a RCP."},{"id":5266,"materia":"enf","nivel":1,"enunciado":"Em equipo de macrogotas, 1 mL corresponde a:","opcoes":["20 gotas","60 gotas","10 gotas","100 gotas"],"explicacao":"Em microgotas, 1 mL corresponde a 60 microgotas."},{"id":5267,"materia":"enf","nivel":1,"enunciado":"Em bebês, a frequência respiratória deve ser contada:","opcoes":["Por 1 minuto inteiro, observando o abdome","Por 10 segundos e multiplicando o resultado por 6","Com o bebê chorando","Só pelo som do nariz"],"explicacao":"O ritmo do bebê é irregular, por isso conta-se o minuto todo."},{"id":5268,"materia":"enf","nivel":1,"enunciado":"A lesão por pressão em estágio 1 se caracteriza por:","opcoes":["Pele íntegra com vermelhidão que não some ao ser pressionada","Bolha rompida, com perda parcial da pele e leito rosado e úmido","Perda total da pele com gordura visível","Exposição de osso e tendão"],"explicacao":"É o momento de aliviar a pressão para impedir a evolução."},{"id":5269,"materia":"enf","nivel":1,"enunciado":"Na fístula arteriovenosa para hemodiálise, no braço da fístula não se deve:","opcoes":["Medir a pressão nem puncionar veias","Fazer higiene diária com água e sabão neutro","Palpar o frêmito","Movimentar a mão"],"explicacao":"O frêmito (vibração) indica que a fístula está funcionando."},{"id":5270,"materia":"enf","nivel":1,"enunciado":"Após administrar dieta ou medicamento pela sonda enteral, deve-se:","opcoes":["Lavar a sonda com água, conforme protocolo","Deixar a sonda sem lavar até a próxima dieta","Lavar com álcool a 70%","Trocar a sonda a cada dose"],"explicacao":"A lavagem evita obstrução."},{"id":5271,"materia":"enf","nivel":1,"enunciado":"São exemplos de medicamentos de alta vigilância:","opcoes":["Insulina, heparina e cloreto de potássio concentrado","Soro fisiológico e água destilada","Vitamina C, complexo B, soro fisiológico e sais de reidratação oral","Pomada de vaselina e talco"],"explicacao":"Exigem dupla checagem e cuidado redobrado."},{"id":5272,"materia":"enf","nivel":1,"enunciado":"Durante a transfusão de sangue, o paciente deve ser observado com mais atenção nos primeiros:","opcoes":["10 a 15 minutos","5 segundos","24 horas, sem nada nos primeiros minutos","3 dias"],"explicacao":"Reações graves costumam aparecer logo no início."},{"id":5273,"materia":"enf","nivel":1,"enunciado":"A máscara de Venturi é usada quando se quer oferecer oxigênio:","opcoes":["Em concentração controlada e precisa","Em concentração sempre de 100%, sem ajuste possível","Sem nenhum controle","Só para crianças"],"explicacao":"Cada válvula colorida corresponde a uma fração de oxigênio."},{"id":5274,"materia":"enf","nivel":1,"enunciado":"A vacina BCG, depois de aplicada, forma uma lesão que deve ser cuidada:","opcoes":["Sem curativo e sem pomadas, deixando evoluir até a cicatriz","Com curativo fechado por um mês","Com pomada antibiótica diária e curativo fechado até cicatrizar","Espremendo a pústula"],"explicacao":"A lesão passa por nódulo, pústula, úlcera e crosta."},{"id":5275,"materia":"enf","nivel":2,"enunciado":"Prescrição: 1.500 mL de soro em 24 horas, com macrogotas. O gotejamento será de cerca de:","opcoes":["21 gotas/min","62 gotas/min","42 gotas/min","15 gotas/min"],"explicacao":"Gotas/min = volume ÷ (horas × 3) = 1.500 ÷ 72 ≈ 21."},{"id":5276,"materia":"enf","nivel":2,"enunciado":"Prescrição: 750 mg de cefalotina. O frasco de 1 g foi diluído em 10 mL. Devem ser aspirados:","opcoes":["7,5 mL","5 mL","2,5 mL","10 mL"],"explicacao":"1.000 mg em 10 mL = 100 mg/mL; 750 ÷ 100 = 7,5 mL."},{"id":5277,"materia":"enf","nivel":2,"enunciado":"Um soro corre a 40 microgotas/min. A vazão em mL/h é de:","opcoes":["40 mL/h","20 mL/h","60 mL/h","120 mL/h"],"explicacao":"Em microgotas, o número de microgotas/min é igual ao de mL/h."},{"id":5278,"materia":"enf","nivel":2,"enunciado":"Pessoa com 80 kg e 1,60 m de altura tem IMC de cerca de:","opcoes":["31 kg/m²","50 kg/m²","25 kg/m²","13 kg/m²"],"explicacao":"IMC = peso ÷ altura² = 80 ÷ 2,56 ≈ 31,2."},{"id":5279,"materia":"enf","nivel":2,"enunciado":"O leite materno ordenhado cru pode ser guardado na geladeira por até:","opcoes":["12 horas","7 dias","1 mês","30 minutos"],"explicacao":"No congelador ou freezer, por até 15 dias."},{"id":5280,"materia":"enf","nivel":2,"enunciado":"Na Lista de Verificação de Cirurgia Segura (OMS), as checagens são feitas:","opcoes":["Antes da anestesia, antes da incisão e antes de sair da sala","Só na alta hospitalar","Só depois da cirurgia, já na sala de recuperação pós-anestésica","Apenas na internação"],"explicacao":"As três etapas são chamadas de entrada, pausa e saída."},{"id":5281,"materia":"enf","nivel":2,"enunciado":"A escala de Aldrete e Kroulik é usada para:","opcoes":["Decidir a alta da sala de recuperação pós-anestésica","Avaliar o risco de quedas do paciente idoso internado","Avaliar lesões por pressão","Classificar queimaduras"],"explicacao":"Avalia atividade, respiração, circulação, consciência e saturação."},{"id":5282,"materia":"enf","nivel":2,"enunciado":"Quando a remoção de pelos antes da cirurgia é necessária, recomenda-se fazê-la:","opcoes":["Pouco antes da cirurgia, com tricotomizador elétrico","Na véspera, em casa, com lâmina de barbear comum e espuma","Uma semana antes, com cera","Sempre, em todas as cirurgias"],"explicacao":"A lâmina causa microlesões que aumentam o risco de infecção."},{"id":5283,"materia":"enf","nivel":2,"enunciado":"Na gestação, sangramento vermelho vivo e indolor no terceiro trimestre sugere:","opcoes":["Placenta prévia","Descolamento prematuro de placenta","Trabalho de parto normal","Infecção urinária"],"explicacao":"No descolamento, o sangramento costuma vir com dor e útero endurecido."},{"id":5284,"materia":"enf","nivel":2,"enunciado":"Tremores, agitação, alucinações e confusão dois a três dias após parar de beber sugerem:","opcoes":["Delirium tremens (abstinência alcoólica grave)","Intoxicação aguda por excesso de álcool no mesmo dia","Hipoglicemia leve","Crise de ansiedade comum"],"explicacao":"É uma emergência que exige tratamento rápido."},{"id":5285,"materia":"enf","nivel":3,"enunciado":"Em vítima de trauma com Glasgow igual ou menor que 8, recomenda-se:","opcoes":["Garantir via aérea definitiva (intubação)","Dar água por via oral","Apenas observar em casa e reavaliar no dia seguinte","Fazer só curativo"],"explicacao":"Com esse nível de consciência, a pessoa não protege a própria via aérea."},{"id":5286,"materia":"enf","nivel":3,"enunciado":"A coloração arroxeada da mucosa da vagina durante a gestação é conhecida como sinal de:","opcoes":["Chadwick (Jacquemier)","Hegar","Murphy","Godet"],"explicacao":"É um sinal de probabilidade de gravidez."},{"id":5287,"materia":"enf","nivel":3,"enunciado":"A máscara não reinalante com reservatório é usada quando se precisa de:","opcoes":["Altas concentrações de oxigênio","Oxigênio em baixíssimo fluxo, até 1 L/min","Apenas umidificar o ar","Aspirar secreções"],"explicacao":"O reservatório deve estar cheio antes de colocar no rosto."},{"id":5288,"materia":"enf","nivel":4,"enunciado":"Em uma ferida cirúrgica limpa, fechada por sutura, o curativo estéril costuma ser mantido por:","opcoes":["24 a 48 horas","7 dias sem trocar","Nenhum período, nunca se cobre","30 dias"],"explicacao":"Depois, a ferida pode ficar exposta, se estiver seca."},{"id":5289,"materia":"sus","nivel":0,"enunciado":"A vacinação é um exemplo de prevenção:","opcoes":["Primária","Secundária","Terciária","Quaternária"],"explicacao":"A prevenção primária evita que a doença apareça."},{"id":5290,"materia":"sus","nivel":0,"enunciado":"Uma doença que se espalha por vários países e continentes caracteriza uma:","opcoes":["Pandemia","Endemia","Surto local","Epidemia restrita a um bairro"],"explicacao":"Foi o caso da covid-19."},{"id":5291,"materia":"sus","nivel":0,"enunciado":"A Lei nº 11.108/2005 garante à parturiente:","opcoes":["Um acompanhante de sua escolha no trabalho de parto, parto e pós-parto","Parto cesáreo em qualquer caso","Licença-maternidade de um ano para a mãe e licença de seis meses para o pai","Escolher o médico do hospital"],"explicacao":"O acompanhante é indicado pela própria mulher."},{"id":5292,"materia":"sus","nivel":1,"enunciado":"O rastreamento para encontrar a doença antes dos sintomas é um exemplo de prevenção:","opcoes":["Secundária","Primária","Terciária","Quaternária"],"explicacao":"A prevenção terciária trata e reabilita para reduzir sequelas."},{"id":5293,"materia":"sus","nivel":1,"enunciado":"A Constituição (art. 198) define como diretrizes do SUS:","opcoes":["Descentralização, atendimento integral e participação da comunidade","Centralização na União, atendimento seletivo e cobrança dos usuários","Atendimento só de urgência","Cobrança de taxas dos usuários"],"explicacao":"O atendimento integral prioriza as ações preventivas, sem prejuízo das assistenciais."},{"id":5294,"materia":"sus","nivel":1,"enunciado":"Pela Constituição (art. 199), a assistência à saúde:","opcoes":["É livre à iniciativa privada","É proibida às empresas privadas","Só pode ser feita pelos estados","Só pode ser feita pela União"],"explicacao":"O setor privado pode participar do SUS de forma complementar."},{"id":5295,"materia":"sus","nivel":1,"enunciado":"Segundo o Decreto nº 7.508/2011, a RENASES é a:","opcoes":["Relação Nacional de Ações e Serviços de Saúde","Rede de Saúde dos Estados","Relação Nacional de Agentes e Servidores da Saúde","Reserva Nacional de Sangue"],"explicacao":"A RENAME é a relação de medicamentos."},{"id":5296,"materia":"sus","nivel":1,"enunciado":"O SIH/SUS registra informações sobre:","opcoes":["Internações hospitalares","Nascidos vivos","Vacinas aplicadas nas campanhas","Óbitos"],"explicacao":"Os atendimentos ambulatoriais ficam no SIA/SUS."},{"id":5297,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Humanização garante, entre outros pontos:","opcoes":["Visita aberta e direito a acompanhante","Proibição de visitas","Atendimento sem acolhimento","Fila por ordem de chegada em qualquer caso"],"explicacao":"Também valoriza o acolhimento com classificação de risco."},{"id":5298,"materia":"sus","nivel":1,"enunciado":"Segundo a Lei nº 8.080/1990, a vigilância epidemiológica é o conjunto de ações que permite:","opcoes":["Conhecer, detectar e prevenir mudanças nos fatores de saúde e doença","Fiscalizar apenas restaurantes e farmácias, sem olhar para as doenças","Comprar remédios para o SUS","Administrar hospitais privados"],"explicacao":"O objetivo é recomendar e adotar medidas de prevenção e controle."},{"id":5299,"materia":"sus","nivel":2,"enunciado":"A letalidade de uma doença é calculada dividindo:","opcoes":["Os óbitos pela doença pelo número de casos da doença","Os óbitos pela doença pela população total da região no período","Os casos novos pela população","Os nascidos vivos pelos óbitos"],"explicacao":"Já a mortalidade usa a população total no denominador."},{"id":5300,"materia":"sus","nivel":2,"enunciado":"Pela Lei Complementar nº 141/2012, os estados devem aplicar em saúde, no mínimo:","opcoes":["12% da receita de impostos","15% da receita de impostos","5% da receita de impostos","25% da receita de impostos"],"explicacao":"Os municípios aplicam no mínimo 15%."},{"id":5301,"materia":"sus","nivel":2,"enunciado":"O CONASEMS representa:","opcoes":["Os secretários municipais de saúde","Os secretários estaduais de saúde e o Distrito Federal","Os médicos do país","Os usuários do SUS"],"explicacao":"O CONASS representa os secretários estaduais."},{"id":5302,"materia":"sus","nivel":2,"enunciado":"Pela PNAB 2017, cada Agente Comunitário de Saúde deve acompanhar, no máximo:","opcoes":["750 pessoas","3.500 pessoas","100 pessoas","10.000 pessoas"],"explicacao":"Em áreas de risco, o número deve ser menor."},{"id":5303,"materia":"sus","nivel":2,"enunciado":"Além dos atributos essenciais, a atenção primária tem atributos derivados como:","opcoes":["Orientação familiar, orientação comunitária e competência cultural","Alta complexidade e cirurgia","Atendimento só por especialistas, com encaminhamento obrigatório ao hospital","Internação prolongada"],"explicacao":"Os atributos foram descritos por Barbara Starfield."},{"id":5304,"materia":"sus","nivel":2,"enunciado":"Na Política Nacional de Humanização, a ambiência refere-se:","opcoes":["Ao espaço físico acolhedor, que favorece o cuidado e o trabalho","Apenas à limpeza do chão","Ao número de leitos de UTI e de enfermaria disponíveis no hospital","Ao horário dos médicos"],"explicacao":"Inclui conforto, privacidade e espaços de encontro."},{"id":5305,"materia":"sus","nivel":2,"enunciado":"A Lei nº 8.080/1990 traz como princípio a organização dos serviços para:","opcoes":["Evitar duplicidade de meios para fins idênticos","Criar serviços repetidos em cada bairro","Centralizar tudo na União","Cobrar por atendimento especializado de quem pode pagar"],"explicacao":"Também prevê a capacidade de resolução em todos os níveis."},{"id":5306,"materia":"sus","nivel":3,"enunciado":"Pelo Decreto nº 7.508/2011, para ser instituída, a Região de Saúde deve ter, no mínimo, ações de:","opcoes":["Atenção primária, urgência, atenção psicossocial, atenção especializada e vigilância em saúde","Apenas hospitais de alta complexidade, com UTI, centro cirúrgico, hemodiálise e maternidade de referência","Somente atenção primária","Apenas vigilância sanitária"],"explicacao":"A atenção ambulatorial especializada e a hospitalar formam um dos itens."},{"id":5307,"materia":"sus","nivel":3,"enunciado":"A Lei nº 8.080/1990 prevê, entre os princípios do SUS:","opcoes":["A capacidade de resolução dos serviços em todos os níveis de assistência","A resolução dos casos só nos hospitais universitários e de alta complexidade","O atendimento apenas na capital","A prioridade a quem paga"],"explicacao":"O usuário deve ter seu problema resolvido no nível adequado."},{"id":5308,"materia":"sus","nivel":4,"enunciado":"Pelo princípio da equidade, numa fila de atendimento, deve ser priorizado:","opcoes":["Quem tem maior risco ou necessidade","Quem chegou primeiro, sempre, sem nenhuma exceção","Quem tem plano de saúde","Quem mora mais perto"],"explicacao":"É a base do acolhimento com classificação de risco."},{"id":5309,"materia":"med","nivel":0,"enunciado":"A doença de Chagas é causada pelo Trypanosoma cruzi e transmitida principalmente:","opcoes":["Pelo inseto barbeiro","Pelo mosquito Aedes aegypti","Por água contaminada com urina de rato","Por picada de carrapato"],"explicacao":"Também pode ser transmitida por alimentos contaminados, como caldo de cana e açaí."},{"id":5310,"materia":"med","nivel":0,"enunciado":"A trava da mandíbula (trismo) e espasmos musculares após ferimento com objeto sujo sugerem:","opcoes":["Tétano","Raiva","Meningite","Dengue"],"explicacao":"A vacinação em dia previne a doença."},{"id":5311,"materia":"med","nivel":1,"enunciado":"A sífilis primária se manifesta por:","opcoes":["Uma ferida única, indolor e de bordas endurecidas (cancro duro)","Manchas vermelhas espalhadas nas palmas das mãos e nas plantas dos pés","Febre alta e tosse","Perda de memória"],"explicacao":"A lesão some sozinha, mas a infecção continua."},{"id":5312,"materia":"med","nivel":1,"enunciado":"Na asma persistente, o medicamento de controle mais importante é:","opcoes":["Corticoide inalatório","Antibiótico","Antiácido","Anti-histamínico em xarope"],"explicacao":"O broncodilatador de curta ação serve para as crises."},{"id":5313,"materia":"med","nivel":1,"enunciado":"Na suspeita de infarto, sem contraindicação, deve-se dar logo:","opcoes":["AAS mastigado","Dipirona","Paracetamol","Água com açúcar"],"explicacao":"O AAS reduz a formação do trombo."},{"id":5314,"materia":"med","nivel":1,"enunciado":"A falta de vitamina B12 ou de ácido fólico causa anemia:","opcoes":["Megaloblástica","Ferropriva","Falciforme","Hemolítica por veneno"],"explicacao":"As hemácias ficam maiores que o normal."},{"id":5315,"materia":"med","nivel":1,"enunciado":"O Ministério da Saúde recomenda mamografia de rastreamento:","opcoes":["A cada 2 anos, para mulheres de 50 a 69 anos","Todo mês, a partir dos 20 anos","Só depois dos 80 anos","Uma vez por ano, para todas as mulheres a partir dos 40 anos"],"explicacao":"Mulheres com risco elevado seguem orientação específica."},{"id":5316,"materia":"med","nivel":1,"enunciado":"Na doença do refluxo, o medicamento mais usado para reduzir a acidez é:","opcoes":["Inibidor da bomba de prótons, como o omeprazol","Antibiótico","Diurético","Corticoide oral em uso contínuo por vários meses"],"explicacao":"Medidas como elevar a cabeceira e evitar comer antes de deitar também ajudam."},{"id":5317,"materia":"med","nivel":1,"enunciado":"Em morte violenta, como homicídio ou acidente, o corpo deve ser encaminhado:","opcoes":["Ao IML (Instituto Médico Legal)","Ao SVO","Direto para a funerária, com atestado do médico de plantão","À unidade básica de saúde"],"explicacao":"O SVO cuida de mortes naturais sem assistência."},{"id":5318,"materia":"med","nivel":2,"enunciado":"Na hanseníase, com o esquema PQT-U, o tratamento dura:","opcoes":["6 meses na paucibacilar e 12 meses na multibacilar","1 semana em todos os casos","5 anos em todos os casos, com doses diárias supervisionadas","3 dias na multibacilar"],"explicacao":"As doses mensais são supervisionadas na unidade de saúde."},{"id":5319,"materia":"med","nivel":2,"enunciado":"Na hepatite B, a infecção é considerada crônica quando o HBsAg continua positivo por mais de:","opcoes":["6 meses","1 semana","10 anos","24 horas"],"explicacao":"A vacina previne a doença."},{"id":5320,"materia":"med","nivel":2,"enunciado":"Febre prolongada, perda de peso, fígado e baço aumentados, em área endêmica, sugerem:","opcoes":["Leishmaniose visceral (calazar)","Gripe comum de evolução arrastada","Escabiose","Conjuntivite"],"explicacao":"É transmitida pelo mosquito-palha."},{"id":5321,"materia":"med","nivel":2,"enunciado":"A pré-eclâmpsia é definida por pressão alta após 20 semanas de gestação com:","opcoes":["Proteinúria ou sinais de lesão de órgãos","Tosse seca","Ganho de peso só nos braços, no rosto e no pescoço","Dor de dente"],"explicacao":"Pode evoluir para eclâmpsia, com convulsões."},{"id":5322,"materia":"med","nivel":3,"enunciado":"No choque séptico que não responde ao volume, o vasopressor de primeira escolha é:","opcoes":["Noradrenalina","Dipirona","Furosemida em altas doses","Diazepam"],"explicacao":"O objetivo é manter a pressão arterial média de pelo menos 65 mmHg."},{"id":5323,"materia":"med","nivel":4,"enunciado":"No diabetes tipo 2, ao iniciar insulina NPH à noite, a dose inicial costuma ser de:","opcoes":["10 UI ou 0,1 a 0,2 UI/kg","100 UI","1 UI/kg de 4 em 4 horas","50 UI pela manhã e 50 UI à noite"],"explicacao":"A dose é ajustada pela glicemia de jejum."},{"id":5324,"materia":"fisio","nivel":0,"enunciado":"Afastar um membro da linha média do corpo é o movimento de:","opcoes":["Abdução","Adução","Flexão","Rotação interna"],"explicacao":"Aproximar da linha média é a adução."},{"id":5325,"materia":"fisio","nivel":0,"enunciado":"A contração em que o músculo trabalha sem mudar de comprimento e sem movimentar a articulação é a:","opcoes":["Isométrica","Concêntrica","Excêntrica","Isotônica com carga"],"explicacao":"Empurrar uma parede é um exemplo."},{"id":5326,"materia":"fisio","nivel":0,"enunciado":"O aumento exagerado da curvatura da coluna lombar é chamado de:","opcoes":["Hiperlordose","Hipercifose","Escoliose","Retificação cervical"],"explicacao":"Pode estar ligada à fraqueza abdominal e ao encurtamento de músculos do quadril."},{"id":5327,"materia":"fisio","nivel":0,"enunciado":"A aplicação de gelo costuma durar cerca de:","opcoes":["15 a 20 minutos","2 horas seguidas","1 minuto","A noite toda"],"explicacao":"Deve-se proteger a pele com um pano."},{"id":5328,"materia":"fisio","nivel":1,"enunciado":"Para subir escadas com muletas e uma perna lesionada, a pessoa deve subir:","opcoes":["Primeiro com a perna sadia","Primeiro com a perna lesionada","Com as duas muletas antes de tudo","Pulando com os dois pés juntos"],"explicacao":"Para descer, vão primeiro as muletas e a perna lesionada."},{"id":5329,"materia":"fisio","nivel":1,"enunciado":"Os movimentos de flexão e extensão do cotovelo acontecem no plano:","opcoes":["Sagital","Frontal","Transversal","Horizontal"],"explicacao":"Abdução e adução ocorrem no plano frontal."},{"id":5330,"materia":"fisio","nivel":1,"enunciado":"Na síndrome de Down, um achado motor comum que exige estimulação precoce é:","opcoes":["Hipotonia muscular","Espasticidade grave","Rigidez em roda denteada","Tremor de repouso"],"explicacao":"A hipotonia atrasa marcos como sentar e andar."},{"id":5331,"materia":"fisio","nivel":2,"enunciado":"Agachamento e leg press são exemplos de exercícios em cadeia cinética:","opcoes":["Fechada, com o pé apoiado","Aberta, com o pé livre no ar e sem apoio","Passiva","Respiratória"],"explicacao":"Na cadeia aberta, a extremidade fica livre, como na cadeira extensora."},{"id":5332,"materia":"fisio","nivel":2,"enunciado":"O sinal de Trendelenburg positivo (quadril que cai do lado sem apoio) indica fraqueza do:","opcoes":["Glúteo médio do lado apoiado","Quadríceps","Tríceps sural","Bíceps femoral do lado sem apoio"],"explicacao":"O glúteo médio estabiliza a pelve durante a marcha."},{"id":5333,"materia":"fisio","nivel":2,"enunciado":"O teste de Finkelstein é usado para investigar:","opcoes":["Tenossinovite de De Quervain","Lesão do menisco","Síndrome do impacto do ombro","Hérnia de disco lombar"],"explicacao":"A dor aparece no lado do polegar, no punho."},{"id":5334,"materia":"fisio","nivel":2,"enunciado":"A lesão do nervo radial costuma causar:","opcoes":["Mão caída (punho caído)","Pé caído","Garra de todos os dedos","Ombro congelado"],"explicacao":"O paciente não consegue estender o punho e os dedos."},{"id":5335,"materia":"fisio","nivel":2,"enunciado":"No paciente hemiplégico, deve-se evitar puxar o braço afetado para movê-lo, para prevenir:","opcoes":["Subluxação e dor no ombro","Fratura do fêmur do lado afetado","Escoliose","Pé torto"],"explicacao":"O posicionamento correto do ombro faz parte da reabilitação."},{"id":5336,"materia":"fisio","nivel":2,"enunciado":"Na fibrose cística, a fisioterapia respiratória deve ser feita:","opcoes":["Todos os dias, para eliminar a secreção","Só durante internações","Uma vez por ano","Só durante as internações, quando houver pneumonia"],"explicacao":"A secreção espessa favorece infecções."},{"id":5337,"materia":"fisio","nivel":3,"enunciado":"A técnica de expiração forçada (huffing) é usada para:","opcoes":["Ajudar a eliminar secreção com menos esforço que a tosse","Aumentar a pressão arterial","Fortalecer os músculos das pernas","Reduzir a frequência cardíaca"],"explicacao":"Faz-se uma expiração forçada com a boca e a glote abertas."},{"id":5338,"materia":"fisio","nivel":4,"enunciado":"No desmame da ventilação mecânica, o teste de respiração espontânea costuma durar:","opcoes":["30 a 120 minutos","5 segundos","24 horas","7 dias"],"explicacao":"Se a pessoa tolera bem, avalia-se a extubação."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
